"""Render complete reviewable source/config/docs without recursive copies."""

import hashlib
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
EXCLUDED = {
    ".git",
    ".venv",
    "results",
    "evidence",
    "dist",
    "build",
    "__pycache__",
    ".pytest_cache",
    ".mypy_cache",
    ".ruff_cache",
    ".hypothesis",
}
output = ROOT / "docs/source_reference.md"
parts = [
    "# Full source reference\n\nGenerated by `python tools/render_source_reference.py`. "
    "Each block contains the complete file, with a SHA-256 checksum. "
    "Generated caches/results and this reference itself are excluded.\n"
]
for path in sorted(ROOT.rglob("*")):
    relative = path.relative_to(ROOT)
    if (
        not path.is_file()
        or path == output
        or any(x in EXCLUDED or x.endswith(".egg-info") for x in relative.parts)
    ):
        continue
    data = path.read_bytes()
    text = data.decode("utf-8")
    fence = "`" * max(
        3, max((len(s) for s in text.split() if s and set(s) == {"`"}), default=0) + 1
    )
    language = {".py": "python", ".toml": "toml", ".yaml": "yaml", ".yml": "yaml", ".sh": "sh"}.get(
        path.suffix, "text"
    )
    parts.append(
        f"\n## {relative}\n\nSHA-256: `{hashlib.sha256(data).hexdigest()}`\n\n"
        f"{fence}{language}\n{text}{'' if text.endswith(chr(10)) else chr(10)}{fence}\n"
    )
output.write_text("".join(parts))
print(f"Wrote {output.relative_to(ROOT)}")
